DROP PROCEDURE IF EXISTS add_migration;
DELIMITER ??
CREATE PROCEDURE `add_migration`()
BEGIN
DECLARE v INT DEFAULT 1;
SET v = (SELECT COUNT(*) FROM `migrations` WHERE `id`='20260726005426');
IF v = 0 THEN
INSERT INTO `migrations` VALUES ('20260726005426');
-- Add your query below.

UPDATE `locales_page_text` SET `Text_loc1` = '--13번째 날<br />테라모어 근처의 군대 활동이 늘어났다. 많은 수의 인간들이 도시를 떠나 서둘러 서쪽으로 향했다.<br /><br />--14번째 날<br />도시에서 또 군대가 출동했다. 나는 작은 무리를 따라갔는데, 테라모어에서 한 300미터쯤 멀어지자 그들은 제복을 벗어버렸다. 탈영병일까?<br /><br />--15번째 날<br />오늘 테라모어 군인들이 얘기하는 것을 엿들었는데, 경비병들이 자기 위치에서 떠난다는 소리를 들었다. 탈영병이라는 생각이 맞는 것 같다.$B--16번째 날<br /><br />울레그와 타르길이 임무를 마치고 테라모어 부두로 돌아왔다. 그들은 항구에 정박해 있는 새로운 배, 블리딩 스패로우호를 보았다. 이 배는 아제로스의 메네실 항구에서 온 배이다.<br /><br />내일 울레그와 타르길이 부두로 돌아가 배로 몰래 들어갈 것이다. 그들은 테라모어와 얼라이언스 간의 관계를 밝혀줄 정치 문서를 찾고 싶어한다.$B--17번째 날<br />울레그가 임무를 마치고 돌아왔다. 그는 임무 완수에 실패했고, 타르길은 생포되었다. 울레그를 보내 이 보고서를 나지르에게 전하도록 했다.<br /><br />난 짐을 싣고 테라모어 해안을 떠나는 배가 증가하고 있는 것을 목격해 왔다. 난 여기에 남아 계속해서 감시를 하며 중요한 일은 모두 보고할 생각이다.' WHERE `entry` = 507;
UPDATE `locales_page_text` SET `Text_loc1` = '...절망의 소용돌이에 빠진 듯하다. 처음에는 날 가지고 놀다가 이제 약혼을 해 버리다니. 처음부터 이 무례한 사기꾼은 결국 나에게 상처를 입힐 작정으로 거짓으로 사랑하는 척했던 것이다. 내 안에 어두운 공허감이 생겨나 매순간 커져 가고 있다. 피보다도 고통스러운 눈물을 얼마나 흘렸던가...' WHERE `entry` = 24;
UPDATE `locales_page_text` SET `Text_loc1` = '[...서판의 첫 부분은 닳아 지워졌지만 마지막 부분은 알아볼 수 있습니다...]$B$B그리렉은 정글을 짓밟아 버렸다. 그의 눈은 분노로 불타고 가슴은 우레와 같이 뛰고 있었다. 허공을 향해 분노로 울부짖은 그의 팔을 쳐들었다. 오른쪽 팔을 잃고 나머지 한 쪽 팔만으로 이어온 사냥을 통해 그의 왼쪽 팔은 강하고 튼튼하게 단련되어 있었다. 그는 팔을 찾아 헤맸지만 잃어버린 팔을 찾을 수는 없었다.$B$B그는 그렇게 저주를 퍼붓고 울부짖으며 돌아다녔다. 하지만 그리렉은 오래전부터 정령들에게 귀를 기울이지 않았고 화가 난 정령들은 그의 저주를 아랑곳하지 않았다. 비참한 운명의 그리렉, 그는 팔 없이 헤매야 할 운명을 맞은 것이었다.' WHERE `entry` = 62;
UPDATE `locales_page_text` SET `Text_loc1` = '가시덤불 골짜기의 푸른 언덕 - 첫째 날은 보통 그렇듯이 순조롭게 지나갔다. 우리는 기지 구축을 위해 필요한 준비를 하는 데 대부분의 시간을 보냈다. 나는 담수가 흘러드는 강어귀 가에서 이상적인 장소를 찾아냈다. 근처에 낡고 버려진 부두가 있는 걸로 보아 이곳은 예전에 어떤 종족이 거주하던 곳인 것 같다. 그러나 원래 누가 살던 땅이었는지는 시간이 흘러야만 알 수 있을 것이다.' WHERE `entry` = 95;
UPDATE `locales_page_text` SET `Text_loc1` = '골짜기의 달은 밝게 빛나리. 조국의 신성한 영토를 수호하라는 부름에 귀 기울이는 자랑스러운 전사들이 있는 정글 위를 밝게 비추고 있나니. 골짜기의 달은 밝게 빛나리. 저 높은 곳에서 적과 아군이 함께 피 흘리는 전투의 울음소리를 비추고 있나니.$B$B그리고 우리 형제들이 미지의 땅을 지날 때, 골짜기 아래 깊은 곳에서 그들의 영혼이 강건해지리. 그리고 우리 형제들이 산맥의 신전을 지날 때 우리는 신성한 파란 수정 속에 깃든 그들의 영원한 영혼을 지켜야 하리. 그리고 우리 형제들이 지날 때 골짜기의 달은 밝게 빛나리.' WHERE `entry` = 58;
UPDATE `locales_page_text` SET `Text_loc1` = '그렐린,<br /><br />난 앞으로 살아갈 날이 얼마 남지 않았고 많은 골칫거리들이 내 수명을 재촉하고 있군그래. 부디 트롤에 대한 자네의 조사만은 순조롭게 진행되길 바라네. 트롤을 상대하는 데 필요하다면 언제든지 내 권위를 사용할 수 있도록 허락하지. 그렇게 해서 적절한 해결책을 찾을 수 있다면 말일세.<br /><br />마그니 브론즈비어드' WHERE `entry` = 80;
UPDATE `locales_page_text` SET `Text_loc1` = '그의 총이 반동으로 그의 팔 안에서 심하게 흔들렸다. 그리고 통이 옆으로 떨어져 아제크는 총 아래로 굴러갔다. 아제크는 바로 그 순간 방아쇠를 당겼다. 갑자기 굴러온 통으로 조준이 흐트러져 총알은 뚜렷한 소리를 내며 나무 있는 곳을 향해 발사되고 말았다. 새 떼가 울부짖으며 하늘로 날아올라 사방으로 흩어졌다. 나무에서 연기가 나고 있었다. 우리는 거대한 나뭇가지가 똑바로 떨어져 달아나는 표범의 등을 부러뜨리는 광경을 두려워하며 지켜보았다.' WHERE `entry` = 112;
UPDATE `locales_page_text` SET `Text_loc1` = '나는 내 부족과 내 집이 그리워. 평야의 바람이나 천둥 벼랑 위의 일몰을 기꺼이 환영합니다.나는 내게 멀지 않은 바다의 물을 볼 수 있지만 내 몸이나 기질을 식히는 데는 아무런 도움이되지 않습니다. 내 감옥에 대해서만 생각 나게한다.' WHERE `entry` = 310;
UPDATE `locales_page_text` SET `Text_loc1` = '닐스 수사님,<br /><br />제 포도는 무사합니다! 이 포도 수확 목록을 지니고 있는 &lt;name&gt; 씨가 용감하게도 악당들이 득실거리는 제 포도밭에 들어가 제가 가져오지 못한 포도를 가져와주었답니다. 강 건너편에서는 아직도 데피아즈단이 어슬렁거리고 있지만 제 포도는 거의 다 구했습니다. 수사님의 저장고에 포도를 한 부대 더 두셔도 좋습니다.<br /><br />성스러운 빛의 가호가 함께 하길.<br /><br />-밀리 오스워드 올림' WHERE `entry` = 1392;
UPDATE `locales_page_text` SET `Text_loc1` = '당시에는 잔질을 피해 그 썩어가는 배에서 도망가는 것이 현명하다고 생각했지만 갑자기 그대로 죽는 편이 더 나을지도 모른다는 생각이 들기 시작했다.<br /><br />우리 조상들의 가호로 살아남을 수 있었다고 생각했다. 하지만 지금은 평생 갇혀 살아야 한다면 무엇이 현명한 길인지 의문이 든다.' WHERE `entry` = 308;
UPDATE `locales_page_text` SET `Text_loc1` = '로데론에서 있었던 켈투자드의 성공으로 리치 왕은 인간 문명에 대한 공격을 감행하기 위한 최종 준비를 마쳤다. 그의 역병의 힘을 역병 가마솥이라는 이동 가능한 용기 여러 개에 담은 후, 넬쥴은 켈투자드에게 그 가마솥들을 로데론으로 수송하라고 명령했다. 그리고 그곳에서 이교도 집단이 장악한 여러 마을 안에 가마솥들을 숨겨 놓을 계획이었다.$B그러면 충성스러운 이교도들의 보호를 받은 가마솥은 전염병 생성기로 작동하게 되고 아무 것도 모르고 있던 로데론 북부의 농장과 도시들에 역병을 퍼뜨리게 되는 것이다.<br /><br />리치 왕의 계획은 완벽하게 성공하여 로데론 북부 마을들 중 다수가 거의 즉시 오염되었다. 노스렌드에서와 마찬가지로, 역병에 걸린 주민들은 죽음을 맞았고 그 후 리치 왕의 자발적인 노예로 되살아났다.$B켈투자드 수하의 이교도들은 기꺼이 죽기를 자처했고 어둠의 지배자의 충성스러운 신하로 다시 살아났다. 그들은 언데드로 불사의 몸이 될 수 있으리라는 희망에 기뻐 날뛰었다. 역병이 번지면서 북부 지역에 점점 더 많은 수의 죽음의 좀비들이 나타났다. 켈투자드는 점점 더 수가 불어나는 리치 왕의 군대를 지켜보며 ''스컬지''라 이름 붙였다. 이는 곧 로데론 성문으로 진격하였는데 이는 이 세계에서 인류를 완전히 제거해 버릴 것이라는 의미를 담고 있었다.' WHERE `entry` = 572;
UPDATE `locales_page_text` SET `Text_loc1` = '모건 래디모어는 선량한 사람들과 가난한 자들, 그리고 고통 받는 이들을 보호하기 위해 싸웠던 위대하고 고귀한 기사였다. 여러 해 동안 그는 아제로스 외곽 지역에서 열심히 싸우며 고통받는 자들의 짐을 덜어 주고 악한 자들에게는 신속히 정의의 심판을 내렸다.<br /><br />그는 18세 되던 해 여름, 리스라는 어린 소녀와 결혼했다. 그들은 서로 깊이 사랑했으며 아들 하나와 딸 둘, 모두 세 아이를 낳았다.$B로데론에서 전쟁이 발발하던 당시 모건은 32세였다. 모건은 전설적인 성기사인 빛의 수호자 우서 경의 부름을 받아 그와 함께 오크와 언데드에 맞서 싸웠다. 아내와 아이들을 안전한 집에 남겨두고 모건은 전쟁터로 향했다.<br /><br />전쟁은 몇 해가 흐르도록 계속되었고, 모건은 은빛 성기사단의 해체, 우서의 죽음, 역병의 확산과 같은 많은 끔찍한 일들을 겪었다. 그가 온전한 정신을 유지할 수 있었던 것은 오직 언젠가 아내와 아이들을 다시 만나게 되리라는 희망 때문이었다.$B마침내 모건은 고향으로 돌아왔지만 그가 기억하는 고향과는 전혀 다른 모습뿐이었다. 울창했던 숲은 오염되어 언데드와 다른 악의 세력이 창궐해 있었다. 어딜 가나 파괴된 집과 농장이 즐비했고, 까마귀 언덕 근처의 공동 묘지가 이제 지역의 대부분을 차지하고 있었다. 놀라고 당황한 모건은 집으로 향했으나 그곳엔 폐허만이 있을 뿐이었다.$B고향에 무슨 일이 일어난 것인지 알 수 없었던 그는 아내와 아이들을 만나게 되길 바라면서 사정을 알아보기 위해 마을로 향했다. 모건은 가족에 대해 수소문해 봤으나 아무도 아는 이가 없었다. 그러던 중 그는 다크샤이어라는 곳의 한 사제로부터 까마귀 언덕에 있는 묘지에서 묘비를 찾아보라는 말을 듣게 되었다. 모건은 가족이 세상을 떠났으리라고는 생각지 못하고 그늘숲의 모든 농장과 집을 계속 찾아다녔지만 소용이 없었다.$B그는 혹시 가족이 안전을 위해 도피했을지도 모른다는 생각에 다크샤이어에서 근방의 레이크샤이어로 가 보았다. 도중에 그는 혹시나 하는 마음으로 까마귀 언덕 묘지에 들르기로 했다. 묘비들 사이를 몇 시간 동안 헤매던 모건은 전에 알던 사람들의 이름을 많이 발견하고 점점 더 깊은 불안에 빠져 갔다. 결국 많은 무덤 가운데 아무렇게나 방치되어 있는 작은 땅덩이와 세 개의 작은 묘비를 보게 되었다. 가까이 다가갈수록 공포가 그를 엄습했다.$B모건은 그 중 가장 큰 묘비의 먼지를 쓸어내고 묘비에 쓰인 이름을 확인했다. 무덤 위에 단출하게 새겨져 있는 다음과 같은 글자는 그의 끔찍한 공포를 현실로 확인시켜 주었다.<br />리스 래디모어<br />한 남자의 사랑스런 아내이자 아이들의 어머니, 여기 잠들다<br />모건의 불안은 경악으로 바뀌었고, 그리고 다시 그것은 깊은 슬픔이 되었다. 그는 무릎을 꿇고 앉아 눈물을 흘리기 시작했다. 여러 시간 동안 그 무덤을 바라보며 차가운 묘비에 흐느껴 울며 용서를 빌었다.$B그리고 몇 시간이 흐른 뒤 그는 안에서 뭔가가 번쩍한 듯 급히 움직이기 시작했다. 검집에서 검을 꺼내 들자 묘비 위로 비바람이 일기 시작했고 그는 분노로 울부짖었다. 분노에 사로잡힌 그는 거친 몸짓으로 검을 크게 휘둘렀고 세 명의 묘지기의 눈에 띄게 되었다. 그들이 그를 진정시키려 하자 그는 죄 없는 묘지기들을 향해 비난의 말을 퍼붓고는 모두 죽여 버렸다.$B잠시 후 분노가 가라앉고 정신을 차린 모건의 눈에는 묘지기 중 한 명의 가슴에 박힌 피 묻은 그의 검이 들어왔다. 복받치는 감정을 이기지 못한 그는 허리에 차고 있던 칼을 꺼내 자신의 심장을 찔렀다. 이튿날 모건 래디모어의 시신과 그에게 희생된 다른 세 구의 시신이 발견되었다. 그는 장례식도 없이 묘지 한쪽 구석에 급히 만든 무덤에 바로 매장되었다. 평소 그의 신념이나 본성과는 정반대로 죄 없는 이들을 살해했다는 사실과$B가족을 지키지 못했다는 슬픔으로 모건은 평온하게 죽을 수 없었고 편히 잠들지 못하는 영혼으로 남게 되었다. 불과 며칠 후에 그의 무덤이 다시 파헤쳐졌으나 시신을 찾을 수 없었다. 모건은 이제 아내와 아이들을 잃은 슬픔과 자기 혐오로 자신을 질책하며 그늘숲을 떠돌고 있다. 스스로 모르라딤이라 칭하며 어리석은 복수심과 증오에 눈이 멀어 무차별적으로 살인을 저지르는 것으로 알려져 있다.' WHERE `entry` = 64;
UPDATE `locales_page_text` SET `Text_loc1` = '못난 바보들!<br /><br />내 계획은 두 다리를 동시에 파괴하는 것이었다. 그런데 어리석은 네놈들은 어떻게 했느냐? 다리는 하나밖에 파괴하지 못했고 동맹 전체에 우리 계획만 알리는 꼴만 되지 않았느냐. 바보 같은 놈들!<br /><br />네놈들의 실수를 만회할 마지막 기회를 주겠다. 예비 폭탄을 아라시 고원의 다리에서 그리 멀지 않은 곳에 숨겨 두었다.<br /><br />네놈들의 임무를 완수하고 살아 있을 가치가 있다는 걸 증명하라!<br /><br />- 캄 딥퓨리' WHERE `entry` = 316;
UPDATE `locales_page_text` SET `Text_loc1` = '베소르 아이스샤드 경<br /><br />경의 뜻에 따라 요청하신 요원을 보냅니다. 바로 이 명령서를 가져가는 이가 적임자입니다.<br /><br />이 자는 믿을 만하고 충분히 명령을 수행할 능력이 있음을 보여 주었습니다. 스컬지 군대를 상대로 능력을 입증해 보인 자이니만큼 경의 임무에 적격일 거라고 생각합니다.<br /><br />여왕 폐하의 영광이 있기를...<br />- 집정관 세브렌 올림' WHERE `entry` = 244;
UPDATE `locales_page_text` SET `Text_loc1` = '블리딩 스패로우호: 적하 물품 및 승객 목록<br /><br />럼주 20통. 목적지: 테라모어<br />밀가루 50포대. 목적지: 테라모어<br />여러 가지 노움 공구 2상자. 목적지: 톱니항<br />면직물 30필. 목적지: 테라모어<br />양념 4상자. 목적지: 테라모어<br />승객 3명. 목적지: 테라모어$B선장,<br />여행에 행운이 함께하길 바랍니다. 안타깝게도, 우리의 첫 유괴 시도에는 행운이 따라 주지 않았습니다. 우리들이 스톰윈드와 아이언포지 동굴에서 목표물과 마주대한 그것이 유인용 미끼임을 알게 되었습니다. 그는 우리가 생각했던 것보다 더 영리한 자였던 것 같습니다.<br />하지만 두 번째 계획이 이미 실행 중입니다. 데피아즈 첩보원들은 목표물이 테라모어에 접근할 때 중간에 붙잡아 올 만반의 준비가 되어 있습니다. 곧 스톰윈드는 우리로 인해 뼈아픈 고통을 맛보게 될 것입니다.<br />- M' WHERE `entry` = 527;
UPDATE `locales_page_text` SET `Text_loc1` = '사랑하는 이베트<br /><br />이 편지를 가장 빠른 전령에게 맡기도록 하겠소. 전령이 우리를 포위하고 있는 적진을 뚫고 무사히 빠져나가기를 기원하오. 그리고 내가 전하는 마지막 소식이 될 이 편지를 당신이 읽을 수 있기를 간절히 바라오이다.<br /><br />그래도 이 암울한 시기에 당신만은 무사하다는 사실이 내게 유일한 위안이라오.$B아버지께서 남아 우리 가족을 지키기로 결정하신 것이 큰 실수가 아니었는지 걱정스럽소. 스컬지 군대가 티리스팔 숲을 통해 무서운 기세로 진격하고 있고, 우리가 만반의 방어 태세를 갖췄다고 해도 내 형제 데블린의 배반 이후에 우리는 놈들의 계속되는 공격에 저항할 힘과 병력이 부족한 실정이오.<br /><br />이베트, 이 편지를 받으면 데블린이 배반자라는 사실을 꼭 알아 두기 바라오.$B데블린은 실의에 빠져 불운 속에서 빠져나올 탈출구를 찾고 있었고 그러던 중 스컬지와 계약을 맺게 된 것이오. 어떤 보상을 약속받았기에 배신을 한 것인지는 모르지만, 내 생각엔 그럴듯한 거짓말일 것이 자명하오.<br /><br />그를 보게 되면 도망치도록 하시오. 그는 이제 악귀일 뿐이니까 말이오. 며칠 전 밤 그는 우리 경비병 둘을 살해하고 소규모 스컬지 부대를 잠입시켜 다수의 아군이 취침하고 있는 곳으로 데려왔었소.$B놈들의 매복 공격은 잔인했소. 우리는 미처 반격하기도 전에 삼분의 일이 희생됐소. 이제 변경을 지킬 경비병도 부족할 실정이오. 우리의 빈약한 방어선이 무너지고 스컬지가 공격해 오는 건 이제 시간 문제일 뿐이오.<br /><br />그 저주받은 밤에 절망적인 얼굴의 사람들과 음산한 얼굴의 스컬지들 사이에서 데블린의 얼굴을 봤지만 그는 내가 붙잡기 전에 사라져 버렸소. 아마 벌써 죽었거나 아니면 아직도 스컬지의 앞잡이로 살고 있겠지.<br /><br />어쨌든, 그는 이제 괴물이오.$B데블린은 우리가 스컬지에 대항하려 하면 비참한 최후를 맞게 될 거라고 경고했었소. 그들이 티리스팔 숲에 처음 발을 들여놓았을 때 우리에게 그런 얘길 했었지. 우리를 포위하기 훨씬 전에 말이오. 아마 그는 우리가 떠나기를 간절히 바랬던 것이거나, 아니면 회심의 미소를 짓고 있었던 것일지도 모르지.<br /><br />데블린은 언제나 진의를 파악하기 힘든 자였소. 그는 어렸을 때부터 우리에게 수수께끼 같은 존재였지.$B하지만 결국 그가 옳았고 우리는 비참한 최후를 맞았소. 아가만드 가문은 이제 여기서 끝나는가 보오. 아직은 살아 있지만 나도 곧 죽게 되리라는 것을 알고 있소.<br /><br />난 두렵지 않고 내 가족과 함께 남아 있었던 것에 대해 일말의 후회도 없소. 하지만 결국 마지막에 떠오르는 건 당신이구려.<br /><br />사랑하는 이베트, 당신은 반드시 살아 남아야 하오. 내가 편히 눈감을 수 있도록.<br />- 투르만' WHERE `entry` = 214;
UPDATE `locales_page_text` SET `Text_loc1` = '사랑하는 타렐에게<br />서둘러 답장을 써서 미안해요. 하지만 지금 이곳에서는 시간이 넉넉지 않답니다.<br /><br />발굴단은 상당한 진척을 이루어 중요한 티탄 유물들을 발굴해 냈어요. 그런데 추가로 커다란 뼈와 같은 다른 고대 유물들도 발견되기 시작했어요.$B뼈 발굴이 시작되고 얼마 지나지 않아 우린 랩터의 공격을 받고 말았어요. 롱브레이드 연대 소속 병력이 용감히 맞서 싸웠지만 결국 놈들에게 제압당하고 말았죠. 거의 전멸하고 우리 세 명만 살아남았으니까요. 오머 아이언브레이드라는 인부가 저와 발굴조사단장 웰가르님을 안전하게 지켜 줬어요. 얼마나 용감하던지...$B지금은 안전한 동굴에 피신해 있어요. 별다른 위험은 없을 것 같아 보이지만 랩터를 처리할 병력이 투입될 때까지 우린 꼼짝없이 갇히게 됐어요. 웰가르님은 작업을 계속하려고 하시지만 아직도 많이 겁을 먹고 계신 것 같아 보여요. 지금 우리는 이런 상황이에요, 타렐. 즉시 구조 병력을 보내도록 롱브레이드님을 설득해 주세요.<br /><br />이런 절박한 상황에서도 당신을 향한 제 사랑은 너무나 강하답니다.<br /><br />- 당신의 아내 메린' WHERE `entry` = 92;
UPDATE `locales_page_text` SET `Text_loc1` = '사랑하는 토미 조,<br />매 순간 당신이 곁에 없다는 사실로 내 심장은 시들어 가고 있답니다. 아, 당신 가족과 우리 가족이 서로에 대한 어리석은 죄를 넘어설 수 있다면... 진정한 죄악이 바로 증오라는 것을 깨닫게 된다면 더 바랄 것이 없겠어요. 이런 암울한 시기에 당신과 나의 가족들뿐만 아니라 더 많은 이들이 증오에 사로잡히게 될까봐 두려워요. 그들 모두 이런 사실을 깨닫게 된다면, 마침내 우리도 함께할 수 있게 될 텐데... 저는 그날을 꿈꾸며, 그날을 위해 살겠어요.<br />당신의 사랑, 메이벨' WHERE `entry` = 25;
UPDATE `locales_page_text` SET `Text_loc1` = '서부정통 스튜 조리법<br /><br />재료:<br />식인독수리 고기 3덩이<br />뿔엄니멧돼지 주둥이 3개<br />멀록 눈알 3개<br />오크라 3개<br /><br />위의 재료를 함께 넣고 적어도 두 시간 이상 푹 끓인 후 그릇에 담아낸다.' WHERE `entry` = 213;
UPDATE `locales_page_text` SET `Text_loc1` = '아거스,<br /><br />자네도 알다시피 나는 군대의 수리 요청으로 눈코 뜰 새 없다네. 일이 많다고 불평할 순 없는 거지만 이제는 철마저 거의 바닥나서 말 편자에 사용할 철이 부족하네.<br /><br />자네는 항상 많은 철을 확보하고 있다고 알고 있네. 그러니 내가 다음번 철괴 상자를 받게 될 때까지 편자 50개를 빌려 준다면 정말 고맙겠네.<br /><br />- 베르너' WHERE `entry` = 28;
UPDATE `locales_page_text` SET `Text_loc1` = '아제로스 대륙은 한없이 경이로운 땅이다. 그 대지 위에는 동식물과 문명, 그리고 마법이 충만하다. 사실, 호기심이 강한 이라면 누구나 이 대륙의 무한한 다양성을 깨닫게 될 것이다. 그냥 둘러보기만 해도 알 수 있으니 말이다.<br /><br />하지만 깊이 관찰하게 되면 완전히 새로운 세계의 창을 발견하게 될 것이며, 각각의 세계에는 저마다 경이로움이 기다리고 있다.<br /><br />각각의 세계에 저마다 공포가 숨어 있는 것처럼...$B이 책을 쓰는 목적은 우리 땅을 파괴하려고 하는 존재, 다른 세계의 악마들을 체계적으로 정리하여 그들과 마주치게 되는 모험가들에게 정보를 주기 위함이다.<br /><br />따라서 스스로 아제로스의 수호자라 여기는 이라면 이 책을 계속 읽기 바라며 적에 대해서 알게 되기를 바란다.<br /><br />- 우르<br />달라란 마술사$B늑대인간에 대해서<br /><br />시골에는 이 생물에 대한 오랜 전설이 전해져 오기 때문에 농부의 자손이라면 누구나 마을 밖의 숲과 늪을 어슬렁거리는 잔인한 늑대인간에 대해 들어 본 적이 있을 것이다.<br /><br />그리고 그런 전설에 진실이 숨어 있을지도 모른다. 우리를 겁주기 위해 신화처럼 베일에 가려진 채 전해오는 늑대인간에 대한 경고는 아닐까?$B하지만 그런 전설을 제쳐놓기 전에 독자들에게 한 가지 확실히 해 두어야겠다. 늑대인간은 실제로 존재한다. 우리 세계의 존재는 아닐지 몰라도 그들의 세계와 우리 세계를 연결하는 통로가 존재하며 강력한 마법을 사용해 그들을 이곳으로 불러올 수 있다.<br /><br />늑대인간은 지나는 곳마다 공포와 살육을 가져오기 때문에 그러한 주문은 언급하지 않는 것이 최선이다.$B늑대인간은 우리 세계의 늑대와 비슷한 외모를 가지고 있어 쉽게 알아볼 수 있다. 자세히 살펴보면 거친 털, 뾰족한 귀, 그리고 긴 주둥이에서 늑대인간은 우리가 아는 늑대와 유사하다는 사실을 알 수 있다.<br /><br />하지만, 차이점 역시 금방 눈에 띈다. 강인한 몸을 지탱하는 두 다리를 굵은 털이 뒤덮고 있으며, 긴 송곳니와 칼처럼 날카로운 발톱이 두드러져 보인다. 그리고 그 울음소리 뒤에는 자연의 짐승에게는 찾아볼 수 없는 증오가 숨어 있다.$B늑대인간의 고향은 악몽이 가득한 장소인 어둠의 땅이다. 만약 그 세계에 저주받은 늑대인간으로부터 안전한 곳이 있다면 내 연구를 통해서는 아직 그런 요새를 알아 내지 못했다. 그리고 늑대인간의 잔인함과 사악한 면으로 미루어 볼 때 그런 곳은 존재하지 않을 가능성이 크다.<br /><br />일부 늑대인간은 강력한 마법을 지니고 있으면서도 스스로 아제로스에 들어오려는 시도를 하지 않은 것으로 보아 자신들의 세계에 머무르는 데 만족하는 것 같다. 그리고 그 점이 우리로서는 다행이 아닐 수 없다.$B위에서 언급했듯이, 일부 늑대인간들은 신비로운 기술을 사용하는 데 능숙하며 그들이 사용하는 마법은 어둠과 타락의 마법이다.<br /><br />보통 저주와 초자연적인 독약을 사용하므로 주의해야 한다. 즉, 늑대인간 마법사를 상대하는 이들은 어둠을 상대할 수 있는 방어 태세를 갖추어야 한다.$B정의로운 마음을 가진 자의 양심에 의해서라도 달라란 마술사가 늑대인간을 찾는 일이 일어나지 않기를 바란다. 이 짐승과는 어떠한 계약도 맺을 수 없으며, 어떠한 비밀도 알아낼 수 없고, 아무런 이득도 얻을 수 없기 때문이다.<br /><br />늑대인간은 그들의 세계에 있도록 두는 것이 가장 좋다. 그들이 우리 세계에 나타나고 누구도 그들을 처치하지 못한다면 우리에게 끔찍한 위험이 닥치게 될 것이기 때문이다.' WHERE `entry` = 698;
UPDATE `locales_page_text` SET `Text_loc1` = '연금술사 라이던,<br /><br />이 편지가 빨리 당신에게 전해지기를, 또한 이 편지를 전하는 이가 무사하기를 바라오. 멀리 칼림도어에서 당신의 능력을 필요로 하게 될 것 같은 일이 발생했소. 간단히 설명하도록 하겠소이다.<br />우리의 동맹 타우렌의 고향인 멀고어에서 멀지 않은 돌발톱 산맥에 위기가 닥쳤소. 고블린이 운영하는 투자개발회사가 이 산맥에서 마구잡이로 채굴과 벌목을 강행해 산의 정령들이 격노하고 있소이다.$B이 정령들이 타우렌 주술사와 드루이드의 비호 아래서 여러 방법으로 일으킨 소란이 놈들을 혼란케 하는 것 같소. 타우렌들은 돌발톱 산맥의 투자개발회사를 심각한 위협으로 간주하고 있소. 그들이 위협 요소이든 그렇지 않든, 우린 우리의 동맹을 도와야 하오.<br />라이던, 당신은 독약에 대해 너무나 잘 알고 있지 않소? 돌발톱 산맥의 고블린들을 전염시킬 수 있는 독약을 만들어 줄 수 있겠지?<br /><br />당신의 학식을 존경하는 P. 자마' WHERE `entry` = 448;
UPDATE `locales_page_text` SET `Text_loc1` = '우리는 빽빽하게 우거진 정글을 뚫고 서쪽을 향해 길을 나섰다. 천천히 신중하게 움직이며, 주변의 울창한 덤불 속에 도사리고 있을지 모르는 위험을 경계했다...' WHERE `entry` = 159;
UPDATE `locales_page_text` SET `Text_loc1` = '우주가 어떻게 시작되었는지 정확히 알지 못합니다. 어떤 사람들은 대격변적인 우주 폭발이 무한한 세계가 언젠가는 경이롭고 끔찍한 다양성을 지니고있는 거대한 암흑 세계의 광막으로 뻗어나 가게했다고 이론화했습니다. 다른 사람들은 존재하는 것처럼 우주가 단 하나의 전능 한 존재에 의해 전체적으로 창조되었다고 믿는다.' WHERE `entry` = 575;
UPDATE `locales_page_text` SET `Text_loc1` = '이 데이터의 보안 등급이 너무 높아서 설명하기 위해 새로운 번호가 발명되기까지 기다리고 있습니다!' WHERE `entry` = 1194;
UPDATE `locales_page_text` SET `Text_loc1` = '이 설명서의 페이지를 채우는 소용돌이 치는 기호와 그림은 이해할 수 없을 정도로 난해합니다.' WHERE `entry` = 891;
UPDATE `locales_page_text` SET `Text_loc1` = '이 쪽지의 글자는 표면 전체에서 깜박이고 춤추는 것처럼 보입니다. 그들에게서 의미를 수집하는 것은 불가능합니다 ...' WHERE `entry` = 53;
UPDATE `locales_page_text` SET `Text_loc1` = '일급 기밀 3중 암호화 데이터 카드<br /><br />01010100 01101000 01110010 01100001 01101100 01101100 00100000 01100001 01101110 01100100 00100000 01001010 01100001 01101001 01101110 01100001 00100000 01110011 01101001 01110100 01110100 01101001 01101110 01100111 00100000 01101001 01101110 00100000 01100001 00100000 01110100 01110010 01100101 01100101 00101100 00100000 01001011 00101101 01001001 00101101 01010011 00101101 01010011 00101101 01001001 00101101 01001110 00101101 01000111' WHERE `entry` = 1131;
UPDATE `locales_page_text` SET `Text_loc1` = '저습지의 던 모드르에서<br /><br />사랑하는 사라에게,<br />수일 안으로 탄돌 교각을 감시하기 위해 이동해야 할 것 같소. 이것이 당신에게 보내는 마지막 편지가 될까 두렵소. 내가 이 세상에 존재하지 않게 되었을 때 당신이 내 소식이나마 알 수 있도록 이렇게 몇 줄 적어야겠다는 생각이 드는구려.$B이번 임무는 며칠 걸릴 것으로 보이는데 성공하면 아주 만족스러운 작전이 될 것 같소. 그리고 격전과 죽음이 도사리고 있을 거요. 하지만 내 기꺼이 얼라이언스를 위해 전장에서 쓰러질 각오가 되어 있소.<br /><br />우리가 추구하고 있는 대의에 대해 나는 한치의 의심도 없고 불안하지도 않을 만큼 내 용기와 믿음은 확고하다오.$B아이언포지 왕국이 얼라이언스의 승리에 거는 기대가 얼마나 큰지 알고 있소. 또 우리가 대전쟁에서 피를 흘리며 고통 속에 사라져 간 이들에게 얼마나 큰 빚을 지고 있는지도 잘 알고 있소. 나는 얼라이언스를 수호하고 그 빚을 갚기 위해 이 생에서 내 모든 기쁨을 기꺼이, 아주 기꺼이 희생할 각오가 되어 있소.$B사라, 당신을 향한 내 사랑은 영원할 것이오. 나를 감싸고 있는 강한 사랑의 끈은 오직 전능하신 신만이 끊을 수 있을 것이며, 왕국에 대한 내 충절은 강한 바람처럼 일어나 그 강한 사랑의 끈과 함께 전장에서 나를 굳건히 지탱시켜 주고 있소.$B당신과 함께 한 행복했던 모든 순간들의 기억이 내 머릿속을 스쳐 지나가는구려. 신과 당신, 오랫동안 나의 기쁨이었던 이 두 존재에 대해 너무나 깊이 감사하고 있소. 당신과 함께 살면서 서로 사랑을 나누고 우리 자식들 곁에서 훌륭한 드워프로 성장해 가는 모습을 지켜보게 될 미래에 대한 희망을 포기하고 불살라 버리는 것이 내게 얼마나 힘든 일인지 모를 거요.$B내가 감히 신의 섭리에 도전할 자격이 없다는 건 알지만, 누군가 내가 사랑하는 가족들에게 무사히 돌아가게 될 거라고 속삭이는 소리가 들리오. 어쩌면 공중에 떠다니는 우리 꼬마 에드거의 기도가 내게 전해진 것인지도 모르겠소. 사랑하는 사라, 내가 돌아가지 못하더라도 내가 당신을 얼마나 사랑하는지, 그리고 내가 전장에서 마지막 숨을 거두게 될 때 당신의 이름을 부를 것이라는 사실을 부디 잊지 말기 바라오.<br /><br />내가 저지른 많은 잘못과 당신에게 준 수많은 고통, 그리고 잦은 경솔함과 어리석음을 용서해 주시오.$B내 눈물로 당신의 행복을 막는 더러운 것들을 모두 씻어 내고 이 세상의 모든 악과 싸워 사랑하는 당신과 우리 자식들을 위험으로부터 지킬 수만 있다면 얼마나 기쁘겠소.<br /><br />하지만 그럴 수가 없구려.<br /><br />황천에 가서라도 반드시 당신을 지켜볼 거요. 그리고 당신이 이승에서 세파를 이겨내는 동안 그 곁을 지키며 기다리겠소. 우리가 다시 만나 영원히 함께하게 될 그 날까지...$B하지만 사라, 죽은 자들이 아제로스로 다시 돌아와 그들이 사랑했던 이들 주변을 몰래 맴돌 수 있다면, 나는 기쁜 날이나 슬픈 날이나, 칠흑 같이 깜깜한 밤이나 낮이나 언제나 당신 곁에 머무를 것이오. 당신의 볼에 부드러운 미풍이 분다면 그건 내 숨결일 것이며, 당신의 고동 치는 관자놀이에 서늘한 공기가 느껴진다면 그건 내 영혼이 당신 곁에 있기 때문일 거요. 사라, 내 죽음을 슬퍼하지 마시오. 나는 잠시 당신 곁을 떠나 당신을 기다리고 있다고 생각하시오. 우리는 반드시 다시 만날 테니까.<br /><br />설리' WHERE `entry` = 317;
UPDATE `locales_page_text` SET `Text_loc1` = '줄파락의 나무망치<br /><br />1. 줄파락의 나무망치를 만들려면 우선 동부 내륙지에 있는 줄의 제단으로 가서 트롤 문지기를 처치하여 신성한 나무망치를 얻는다.<br /><br />2. 이 신성한 망치를 진타알로라는 트롤 도시 꼭대기에 있는 제단으로 가지고 간다.<br /><br />3. 제단에서 신성한 나무망치를 사용하면 마력이 부여되면서 줄파락의 나무망치로 변한다.' WHERE `entry` = 1091;
UPDATE `locales_page_text` SET `Text_loc1` = '지는 해를 등지고 저 높은 바위 절벽 위에 서 있는, 지금껏 내가 본 것 중 가장 거대한 맹수의 실루엣을 똑똑히 볼 수 있었다. 소총으로 어설프게 한 번 사격해 보았지만 그 녀석은 꼼짝도 하지 않았다. 녀석은 처음보다 더 우렁차게 으르렁거리더니 이내 사라져 버렸다. 우리는 짐을 챙겨 엄숙한 마음으로 캠프로 돌아왔다.' WHERE `entry` = 105;
UPDATE `locales_page_text` SET `Text_loc1` = '집정관 솔로몬 귀하.<br /><br />죽은 이들에 대해 심심한 조의를 표하는 바이네. 국왕 폐하께서 이러한 상황을 파악하고 계신지 직접 알아보도록 하겠네. 그리고 레이크샤이어에 증원군을 보낼 수 있게 되기를 진심으로 바라고 있네. 귀하를 믿고 하는 이야기지만, 폐하는 요즘 뵙기 어려울 뿐 아니라 좀 이상한 행동을 보이고 계시네.<br /><br />다시 소식 전할 때까지 부디 안녕히.<br /><br />스톰윈드 왕국 장군<br />마커스 조나단' WHERE `entry` = 36;
UPDATE `locales_page_text` SET `Text_loc1` = '쪽지를 주은 자에게<br /><br />이 쪽지를 읽고 있다면 당신은 다음 두 장소 중 하나에 있는 것이다.<br /><br />1. 아즈샤라의 남부 반도.<br /><br />2. 절벽거인의 뱃속<br /><br />둘 다 편히 쉴만한 곳은 못 된다.<br /><br />나도 한때 남부 반도에도 있어 보았고 지금은 뱃속에 앉아 이 쪽지를 쓰고 있다.$B거인의 뱃속에 있으면 생각할 시간이 생기게 된다.<br /><br />내 몸이 결정화되어 가면서 나도 어쩌면 아직도 이 세상에 많은 영웅 중 하나가 나를 구할 수 있을지도 모른다는 희망을 품게 되었다. 내 어떻게든 이 곤경을 벗어나게 되면 그 유령 같은 오크 녀석의 목을 졸라 버리고 싶다!<br /><br />- 윈던 셰이' WHERE `entry` = 1311;
UPDATE `locales_page_text` SET `Text_loc1` = '친애하는 마르텍,<br /><br />나는 지금 곤경에 빠져 자네 도움이 필요하다네. 우리 형제가 경주용 자동차를 제작하고 있는데 튼튼한 피스톤이 필요하네. 여러 가지를 시도해 봤지만 그 어느 것도 강도가 충분치 못하더군. 우리가 만든 새 자동차의 속도를 견뎌 낼 수 있는 게 하나도 없어. 그래서 계속 엔진 고장을 일으키고 있네!<br /><br />자네가 금속 가공에는 전문가이니 꼭 도와주기 바라네. 자네만이 할 수 있는 일일세.$B다음은 피스톤의 사양입니다.<br /><br />길이: 32 WW<br />너비: 12WW<br />무게: 23.5 IBG~25.5 IBG<br />전도율: 70 TC<br />전단력: 98 이상<br />결합 강도: ''엄청 튼튼'' 이상<br />노움의 측정 단위를 잊으셨다면 다음을 참고하세요.<br />WW = ''수염 너비''<br />IBG = ''아주 조금'' 그램<br />TC = ''발가락 털 길이''' WHERE `entry` = 441;
UPDATE `locales_page_text` SET `Text_loc1` = '커글,<br /><br />그대의 새로운 발명품을 몹시 기다리고 있답니다. 어서 빨리 그 발명품을 사용해서 내 연구에 대해 기록하고 싶군요.<br /><br />심부름꾼을 보낼 테니 그에게 맡겨주세요.<br /><br />고마워요.<br /><br />다린 라이트윈드' WHERE `entry` = 1156;
UPDATE `locales_page_text` SET `Text_loc1` = '쿨 티라스 함대 공식 명령서<br /><br />나 프라우드무어 함장은 칼림도어 해안의 최초 상륙 작전을 직접 지휘하겠다.<br /><br />내가 부재 중일 경우에는 부대장 베네딕트가 지휘권을 일임 받는다. 타이라가드 요새에서 12개월 동안 내 소식을 듣지 못할 경우 부대장 베네딕트가 해당 지역을 확보하기 위한 두 번째 작전을 지휘한다.$B그 동안 부관 알베롤드를 보내 칼림도어 대륙의 탐험 임무를 수행하도록 하겠다. 그의 부대는 임무를 완수한 다음 타이라가드 요새의 아군과 합류한다.<br /><br />부관 알베롤드의 임무는 상당한 시간이 소요될 것으로 예상된다. 새로운 땅은 광활하고 위험할 것이다. 그러나 나와 부대장 베네딕트에게 불운이 닥칠 경우 알베롤드의 부대가 요새를 맡도록 한다.<br /><br />저 요새가 우리 수중에 들어올 때까지 우리는 멈추지 않을 것이다.<br /><br />- 함장 프라우드무어' WHERE `entry` = 337;
UPDATE `locales_page_text` SET `Text_loc1` = '필요할 경우 이 정보를 전하도록 하라.<br /><br />티리스팔 지역 사령부<br />대장 멜로즈<br />대장 바콘<br />대장 페린<br /><br />대영주 지령 사항<br /><br />대장 페린, 지시에 따라 현재 주둔 중인 남서쪽 감시탑의 경계를 더욱 강화하라. 추가 보급품은 후일 공급될 것이니 그동안 주변 농장에서 구할 수 있는 대로 물품을 조달하도록 하라.$B브릴 지역의 언데드 조직에 대해 보다 자세한 정찰 및 정보 수집 활동을 펼치도록 하라.<br /><br />대장 바콘, 북쪽 탑 근처에서 언데드의 움직임이 증가하고 있는 것으로 보인다. 신속히 진압하라.<br /><br />대장 멜로즈, 역병지대 변방에서 활동 중인 언데드 조직의 규모에 대한 우려의 목소리가 있다. 몇 주 내에 증원 병력을 그곳으로 보내도록 하겠다.<br /><br />정의의 편에 영광 있으라.' WHERE `entry` = 223;
UPDATE `locales_page_text` SET `Text_loc1` = '힐스브래드 마을의 기록부<br /><br />우리 힐스브래드 주민은 위대한 군주이신 아이언포지의 왕 마그니 브론즈비어드 폐하와 스톰윈드의 왕 안두인 린 폐하께서 다스리는 동맹에 대한 믿음과 헌신을 엄숙히 맹세합니다.<br /><br />위대한 알터랙 산맥 기슭에 위치한 이 아름다운 도시를 관리하고, 폐하와 위대하고 절대적인 동맹에 세금을 납부한 이들을 기록하기 위해 여기에 마을 기록부를 작성합니다.$B집정관 리더퍼드 번사이드: 부채 전액 상환.<br />대장장이 에이버리 베링턴: 부채 전액 상환.<br />서기 호레이스 화이트스티드: 부채 전액 상환.<br />원로 길리스: 부채 전액 상환.<br />원로 후크: 부채 전액 상환.<br />농부 게츠: 부채 전액 상환.<br />농부 레이: 미상환 부채. 추수 시 농산품으로 상환 약속.<br />농부 라이언: 미상환 부채. 지역에서 퇴거.$B농부 칼라바: 미상환 부채. 추수 시 농산품으로 상환 약속.<br />민간인 윌키스: 부채 전액 상환.<br />민간인 보노안: 부채 전액 상환.<br />광부 웰티: 미상환 부채. 청금석 광산으로부터 다음 광석 도착 시 상환 예정.<br />광부 시드니: 미상환 부채. 청금석 광산으로부터 다음 광석 도착 시 상환 예정.<br />광부 하켓: 미상환 부채. 청금석 광산으로부터 다음 광석 도착 시 상환 예정.$B광부 오웰: 미상환 부채. 청금석 광산으로부터 다음 광석 도착 시 상환 예정.<br />광부 피츠제럴드: 미상환 부채. 청금석 광산으로부터 다음 광석 도착 시 상환 예정.<br />민간인 네더런드: 부채 전액 상환.<br />민간인 메이: 부채 전액 상환.<br />현장감독 본즈: 미상환 부채. 청금석 광산으로부터 다음 광석 도착 시 상환 예정.' WHERE `entry` = 261;

